/**
 * NEW-269 / R-112: the brand / organisation name (tenants.business_name), shown as "by <brand>" under a
 * gym's name. Same rule as the app (host_onboarding/domain/brand_name.dart): a name generated by app
 * builds up to 25 ("<full name>'s Gym Business") is not a brand, and a brand equal to the gym name adds
 * nothing.
 */
const GENERATED_SUFFIX = "'s Gym Business"

export function typedBrandName(stored?: string | null): string {
  const name = (stored ?? '').trim()
  if (!name || name.endsWith(GENERATED_SUFFIX)) return ''
  return name
}

export function brandByline(brand?: string | null, gymName?: string | null): string | null {
  const b = typedBrandName(brand)
  if (!b) return null
  if (b.toLowerCase() === (gymName ?? '').trim().toLowerCase()) return null
  return `by ${b}`
}
